675: func (db *database) getChatWithOptions(id string, loadAttachmentData bool) (*Chat, error) {
676: 	query := `
677: 		SELECT id, title, created_at, browser_state
678: 		FROM chats
679: 		WHERE id = ?
680: 	`
681: 
682: 	var chat Chat
683: 	var createdAt time.Time
684: 	var browserState sql.NullString
685: 
686: 	err := db.conn.QueryRow(query, id).Scan(
687: 		&chat.ID,
688: 		&chat.Title,
689: 		&createdAt,
690: 		&browserState,
691: 	)
692: 	if err != nil {
693: 		if err == sql.ErrNoRows {
694: 			return nil, fmt.Errorf("chat not found")
695: 		}
696: 		return nil, fmt.Errorf("query chat: %w", err)
697: 	}
698: 
699: 	chat.CreatedAt = createdAt
700: 	if browserState.Valid && browserState.String != "" {
701: 		var raw json.RawMessage
702: 		if err := json.Unmarshal([]byte(browserState.String), &raw); err == nil {
703: 			chat.BrowserState = raw
704: 		}
705: 	}
706: 
707: 	messages, err := db.getMessages(id, loadAttachmentData)
708: 	if err != nil {
709: 		return nil, fmt.Errorf("get messages: %w", err)
710: 	}
711: 	chat.Messages = messages
712: 
713: 	return &chat, nil
714: }
