716: func (db *database) saveChat(chat Chat) error {
717: 	tx, err := db.conn.Begin()
718: 	if err != nil {
719: 		return fmt.Errorf("begin transaction: %w", err)
720: 	}
721: 	defer tx.Rollback()
722: 
723: 	// Use COALESCE for browser_state to avoid wiping an existing
724: 	// chat-level browser_state when saving a chat that doesn't include a new state payload.
725: 	// Many code paths call SetChat to update metadata/messages only; without COALESCE the
726: 	// UPSERT would overwrite browser_state with NULL, breaking revisit rendering that relies
727: 	// on the last persisted full tool state.
728: 	query := `
729: 		INSERT INTO chats (id, title, created_at, browser_state)
730: 		VALUES (?, ?, ?, ?)
731: 		ON CONFLICT(id) DO UPDATE SET
732: 			title = excluded.title,
733: 			browser_state = COALESCE(excluded.browser_state, chats.browser_state)
734: 	`
735: 
736: 	var browserState sql.NullString
737: 	if chat.BrowserState != nil {
738: 		browserState = sql.NullString{String: string(chat.BrowserState), Valid: true}
739: 	}
740: 
741: 	_, err = tx.Exec(query,
742: 		chat.ID,
743: 		chat.Title,
744: 		chat.CreatedAt,
745: 		browserState,
746: 	)
747: 	if err != nil {
748: 		return fmt.Errorf("save chat: %w", err)
749: 	}
750: 
751: 	// Delete existing messages (we'll re-insert all)
752: 	_, err = tx.Exec("DELETE FROM messages WHERE chat_id = ?", chat.ID)
753: 	if err != nil {
754: 		return fmt.Errorf("delete messages: %w", err)
755: 	}
756: 
757: 	// Insert messages
758: 	for _, msg := range chat.Messages {
759: 		messageID, err := db.insertMessage(tx, chat.ID, msg)
760: 		if err != nil {
761: 			return fmt.Errorf("insert message: %w", err)
762: 		}
763: 
764: 		// Insert tool calls if any
765: 		for _, toolCall := range msg.ToolCalls {
766: 			err := db.insertToolCall(tx, messageID, toolCall)
767: 			if err != nil {
768: 				return fmt.Errorf("insert tool call: %w", err)
769: 			}
770: 		}
771: 	}
772: 
773: 	return tx.Commit()
774: }
