203: // legacyConfigPath is the path to the old config.json file
204: var legacyConfigPath = func() string {
205: 	switch runtime.GOOS {
206: 	case "windows":
207: 		return filepath.Join(os.Getenv("LOCALAPPDATA"), "Ollama", "config.json")
208: 	case "darwin":
209: 		return filepath.Join(os.Getenv("HOME"), "Library", "Application Support", "Ollama", "config.json")
210: 	default:
211: 		return filepath.Join(os.Getenv("HOME"), ".ollama", "config.json")
212: 	}
213: }()
