279: // migrateCloudSetting migrates legacy airplane_mode into server.json exactly once.
280: // After this, cloud state is sourced from server.json OR OLLAMA_NO_CLOUD.
281: func (s *Store) migrateCloudSetting(database *database) error {
282: 	migrated, err := database.isCloudSettingMigrated()
283: 	if err != nil {
284: 		return err
285: 	}
286: 	if migrated {
287: 		return nil
288: 	}
289: 
290: 	airplaneMode, err := database.getAirplaneMode()
291: 	if err != nil {
292: 		return err
293: 	}
294: 
295: 	if airplaneMode {
296: 		if err := setCloudEnabled(false); err != nil {
297: 			return fmt.Errorf("migrate airplane_mode to cloud disabled: %w", err)
298: 		}
299: 	}
300: 
301: 	if err := database.setCloudSettingMigrated(true); err != nil {
302: 		return err
303: 	}
304: 
305: 	return nil
306: }
