308: // migrateFromConfig attempts to migrate ID and FirstTimeRun from config.json
309: func (s *Store) migrateFromConfig(database *database) error {
310: 	configPath := legacyConfigPath
311: 
312: 	// Check if config.json exists
313: 	if _, err := os.Stat(configPath); os.IsNotExist(err) {
314: 		// No config to migrate, mark as migrated
315: 		return database.setConfigMigrated(true)
316: 	}
317: 
318: 	// Read the config file
319: 	b, err := os.ReadFile(configPath)
320: 	if err != nil {
321: 		return fmt.Errorf("read legacy config: %w", err)
322: 	}
323: 
324: 	var legacy legacyData
325: 	if err := json.Unmarshal(b, &legacy); err != nil {
326: 		// If we can't parse it, just mark as migrated and move on
327: 		slog.Warn("failed to parse legacy config.json", "error", err)
328: 		return database.setConfigMigrated(true)
329: 	}
330: 
331: 	// Migrate the ID if present
332: 	if legacy.ID != "" {
333: 		if err := database.setID(legacy.ID); err != nil {
334: 			return fmt.Errorf("migrate device ID: %w", err)
335: 		}
336: 		slog.Info("migrated device ID from config.json")
337: 	}
338: 
339: 	hasCompleted := legacy.FirstTimeRun // If old FirstTimeRun is true, it means first run was completed
340: 	if err := database.setHasCompletedFirstRun(hasCompleted); err != nil {
341: 		return fmt.Errorf("migrate first time run: %w", err)
342: 	}
343: 	slog.Info("migrated first run status from config.json", "hasCompleted", hasCompleted)
344: 
345: 	// Mark as migrated
346: 	if err := database.setConfigMigrated(true); err != nil {
347: 		return fmt.Errorf("mark config as migrated: %w", err)
348: 	}
349: 
350: 	slog.Info("successfully migrated settings from config.json")
351: 	return nil
352: }
