668: func (s *Server) chat(w http.ResponseWriter, r *http.Request) error {
669: 	w.Header().Set("Content-Type", "text/jsonl")
670: 	w.Header().Set("Cache-Control", "no-cache")
671: 	w.Header().Set("Connection", "keep-alive")
672: 	w.Header().Set("Transfer-Encoding", "chunked")
673: 
674: 	flusher, ok := w.(http.Flusher)
675: 	if !ok {
676: 		return errors.New("streaming not supported")
677: 	}
678: 
679: 	if r.Method != "POST" {
680: 		return not.Found
681: 	}
682: 
683: 	cid := r.PathValue("id")
684: 	createdChat := false
685: 
686: 	// if cid is the literal string "new", then we create a new chat before
687: 	// performing our normal actions
688: 	if cid == "new" {
689: 		u, err := uuid.NewV7()
690: 		if err != nil {
691: 			return fmt.Errorf("failed to generate new chat id: %w", err)
692: 		}
693: 		cid = u.String()
694: 		createdChat = true
695: 	}
696: 
697: 	var req responses.ChatRequest
698: 	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
699: 		fmt.Fprintf(os.Stderr, "error unmarshalling body: %v\n", err)
700: 		return fmt.Errorf("invalid request body: %w", err)
701: 	}
702: 
703: 	if req.Model == "" {
704: 		return fmt.Errorf("empty model")
705: 	}
706: 
707: 	// Don't allow empty messages unless forceUpdate is true
708: 	if req.Prompt == "" && !req.ForceUpdate {
709: 		return fmt.Errorf("empty message")
710: 	}
711: 
712: 	if createdChat {
713: 		// send message to the client that the chat has been created
714: 		json.NewEncoder(w).Encode(responses.ChatEvent{
715: 			EventName: "chat_created",
716: 			ChatID:    &cid,
717: 		})
718: 		flusher.Flush()
719: 	}
720: 
721: 	// Check if this is from a specific message index (e.g. for editing)
722: 	idx := -1
723: 	if req.Index != nil {
724: 		idx = *req.Index
725: 	}
726: 
727: 	// Load chat with attachments since we need them for processing
728: 	chat, err := s.Store.ChatWithOptions(cid, true)
729: 	if err != nil {
730: 		if !errors.Is(err, not.Found) {
731: 			return err
732: 		}
733: 		chat = store.NewChat(cid)
734: 	}
735: 
736: 	// Only add user message if not forceUpdate
737: 	if !req.ForceUpdate {
738: 		var messageOptions *store.MessageOptions
739: 		if len(req.Attachments) > 0 {
740: 			storeAttachments := make([]store.File, 0, len(req.Attachments))
741: 
742: 			for _, att := range req.Attachments {
743: 				if att.Data == "" {
744: 					// This is an existing file reference - keep it from the original message
745: 					if idx >= 0 && idx < len(chat.Messages) {
746: 						originalMessage := chat.Messages[idx]
747: 						// Find the file by filename in the original message
748: 						for _, originalFile := range originalMessage.Attachments {
749: 							if originalFile.Filename == att.Filename {
750: 								storeAttachments = append(storeAttachments, originalFile)
751: 								break
752: 							}
753: 						}
754: 					}
755: 				} else {
756: 					// This is a new file - decode base64 data
757: 					data, err := base64.StdEncoding.DecodeString(att.Data)
758: 					if err != nil {
759: 						s.log().Error("failed to decode attachment data", "error", err, "filename", att.Filename)
760: 						continue
761: 					}
762: 
763: 					storeAttachments = append(storeAttachments, store.File{
764: 						Filename: att.Filename,
765: 						Data:     data,
766: 					})
767: 				}
768: 			}
769: 
770: 			messageOptions = &store.MessageOptions{
771: 				Attachments: storeAttachments,
