1352: 	if chat != nil && len(chat.Messages) > 0 {
1353: 		for i := range chat.Messages {
1354: 			if chat.Messages[i].Role == "tool" && chat.Messages[i].ToolName == "" && chat.Messages[i].ToolResult != nil {
